window.STUDY = {"topics": [{"id": 0, "layer": 1, "start": 1, "end": 3, "title": "Modelos OSI y TCP/IP", "subtitle": "Ubica cada función en su capa", "summary": "OSI organiza la comunicación en siete capas: física, enlace, red, transporte, sesión, presentación y aplicación. El material compara estas funciones con TCP/IP. La capa física transporta bits; enlace organiza tramas; red trabaja con paquetes; transporte conecta procesos."}, {"id": 1, "layer": 1, "start": 4, "end": 11, "title": "Señales y Fourier", "subtitle": "De una señal a su ancho de banda", "summary": "La capa física define interfaces eléctricas y temporización. Una señal periódica puede descomponerse en senos y cosenos. La frecuencia fundamental es f = 1/T y las armónicas son múltiplos enteros de f. Un medio atenúa de forma diferente sus componentes; la frecuencia de corte limita la banda útil y puede distorsionar la señal."}, {"id": 2, "layer": 1, "start": 12, "end": 22, "title": "Cobre y medios guiados", "subtitle": "Coaxial, UTP y cable apantallado", "summary": "Compara ancho de banda, retardo, instalación, costo y vida útil. El coaxial de 50 Ω se presenta para transmisión digital y el de 75 Ω para aplicaciones analógicas y cable. UTP usa cuatro pares trenzados y conector RJ-45. STP protege los pares mediante blindaje; FTP/ScTP incorpora una pantalla general. Las tablas originales comparan categorías y clases."}, {"id": 3, "layer": 1, "start": 23, "end": 44, "title": "Fibra óptica", "subtitle": "Luz, conectores y aplicaciones", "summary": "Una fuente emite luz, la fibra la guía y un fotodetector la convierte en señal eléctrica. El índice de refracción es n = c/v. Multimodo admite distintos modos de propagación; monomodo se emplea para mayores distancias. Estudia conectores, empalme mecánico, fusión, LED, láser y WDM. Ventajas: gran ancho de banda, baja atenuación e inmunidad electromagnética. Requiere cuidado mecánico e interfaces ópticas."}, {"id": 4, "layer": 1, "start": 45, "end": 46, "title": "Datos por la red eléctrica", "subtitle": "Aprovechar el cableado de energía", "summary": "Las líneas eléctricas pueden transportar datos además de energía. Su atenuación en altas frecuencias y el ruido al encender o apagar aparatos dificultan la transmisión; el material destaca técnicas resistentes a ráfagas de errores."}, {"id": 5, "layer": 1, "start": 47, "end": 71, "title": "Radio y microondas", "subtitle": "Espectro, propagación y bandas", "summary": "La frecuencia mide oscilaciones por segundo y la longitud de onda separa dos máximos. En el vacío λ · f = c. Compara radio omnidireccional y microondas direccionales, obstáculos, lluvia, línea de vista y repetidores. El material introduce asignación del espectro, ITU, FCC y bandas ISM. Las fechas, cifras de equipos y disponibilidad de bandas se conservan como contenido histórico de las diapositivas."}, {"id": 6, "layer": 1, "start": 72, "end": 76, "title": "Infrarrojo y luz libre", "subtitle": "Enlaces ópticos sin cable", "summary": "El infrarrojo sirve para distancias cortas y no atraviesa objetos sólidos. La óptica de espacio libre usa haces de luz entre puntos: ofrece gran ancho de banda, pero exige alineación y se ve afectada por niebla, lluvia y condiciones atmosféricas."}, {"id": 7, "layer": 1, "start": 77, "end": 110, "title": "Satélites de comunicaciones", "subtitle": "GEO, MEO, LEO y VSAT", "summary": "Un satélite funciona como repetidor de microondas. Sus transpondedores reciben, amplifican y retransmiten en otra frecuencia. GEO aparece a unos 35.800 km y con período de 24 horas; MEO y LEO requieren seguimiento y tienen distintas coberturas y retardos. Repasa huella, VSAT, órbita, Iridium, Globalstar y CubeSat. Los ejemplos y cifras pertenecen al material original."}, {"id": 8, "layer": 2, "start": 1, "end": 12, "title": "Funciones y servicios de enlace", "subtitle": "De paquetes a tramas", "summary": "La capa 2 ofrece servicios a red, encapsula paquetes en tramas, maneja errores y regula el flujo. Una trama tiene encabezado, carga útil y final. Compara servicios sin conexión sin confirmación, sin conexión con confirmación y orientados a conexión con confirmación. La confiabilidad depende del servicio y protocolo, no solo de pertenecer a la capa 2."}, {"id": 9, "layer": 2, "start": 13, "end": 27, "title": "Entramado", "subtitle": "Reconocer el inicio y el fin", "summary": "Los métodos estudiados son conteo de bytes, banderas con relleno de bytes, banderas con relleno de bits y violaciones de codificación física. En relleno de bits, la bandera es 01111110: se inserta un 0 después de cinco 1 consecutivos en los datos y el receptor lo elimina. La trama genérica incluye delimitación, direcciones, control o longitud/tipo, datos y verificación."}, {"id": 10, "layer": 2, "start": 28, "end": 33, "title": "IEEE y redes inalámbricas", "subtitle": "Acceso compartido al medio", "summary": "El documento presenta comités IEEE 802 y tecnologías WLAN. En radio compartida pueden producirse colisiones; WLAN utiliza CSMA/CA para reducirlas. La comparación con CSMA/CD ayuda a distinguir prevención y detección. Incluye una práctica de campus con AP y laptops en Packet Tracer."}, {"id": 11, "layer": 2, "start": 34, "end": 50, "title": "Ethernet y codificación", "subtitle": "Fast, Gigabit y 10 Gigabit", "summary": "Estudia formatos de trama, medios de cobre y fibra y variantes de Ethernet. Fast Ethernet se presenta a 100 Mb/s y Gigabit a 1000 Mb/s. En 4B/5B, cuatro bits de datos se representan con cinco bits, con eficiencia de 80 %. El material también compara NRZ, NRZI, 8B/10B y variantes de 10 Gigabit; consulta los diagramas originales para las señales."}, {"id": 12, "layer": 2, "start": 51, "end": 61, "title": "NIC, puentes y switches", "subtitle": "Aprender y reenviar por MAC", "summary": "La NIC aporta la interfaz de red. Un puente enlaza segmentos y filtra tráfico mediante direcciones MAC; un switch es un puente multipuerto. Un switch aprende la MAC de origen y reenvía según la MAC de destino. Cada puerto separa dominios de colisión. Las VLAN delimitan dominios de broadcast. La conmutación de capa 3 utiliza información IP."}, {"id": 13, "layer": 2, "start": 62, "end": 65, "title": "Métodos de conmutación", "subtitle": "Latencia y verificación", "summary": "Store-and-forward recibe la trama completa y permite comprobar CRC antes de reenviar. Cut-through comienza antes de recibirla completa, reduciendo la latencia y la verificación previa. Fragment-free espera los primeros 64 bytes. El tráfico broadcast se distribuye dentro del mismo dominio; un destino desconocido se inunda por los puertos correspondientes, excepto el de entrada."}, {"id": 14, "layer": 2, "start": 66, "end": 72, "title": "STP y segmentación", "subtitle": "Evitar bucles de capa 2", "summary": "STP usa BPDU para mantener una topología lógica sin bucles, bloqueando rutas redundantes. Se elige el bridge raíz por el menor identificador de bridge, que considera prioridad y MAC. Los bridges no raíz eligen un puerto raíz según el menor coste hacia la raíz. Repasa puertos designados y estados bloqueado, escuchando, aprendiendo y enviando. La página 72 cierra con una tarea comparativa de switches; no se incluye capa III."}], "pages": [{"layer": 1, "page": 1, "text": "FACULTAD DE LA ENERGÍA LAS\n      INDUSTRIAS Y LOS RECURSOS\n      NATURALES NO RENOVABLES\n\n\n\n      CARRERA EN COMPUTACIÓN\n\n\nFUNDAMENTOS DE REDES Y COMUNICACIONES", "topic": 0}, {"layer": 1, "page": 2, "text": "2.1 CAPAS DEL MODELO OSI, TCP/IP\n Nro.     MODELO               FUNCIONES                   PROTOCOLOS\nCAPA        OSI\n7       Aplicación     Nivel Usuario, Software,        HTTP(80), TELNET(23),\n                       Aplicaciones, Procesos de red   SMNP, FTP, DNS(53),\n                       a aplicaciones                  SSH(22), DHCP(67,68)\n6       Presentación   Representa Datos, Formateo      JPG, MP3, DOC\n                       Cifrado\n5       Sesión         Establece sesiones en           Linux sesiones de\n                       aplicaciones                    múltiples usuarios,\n\n\n\n                                                       comunicación entre host\n4       Transporte     Comunicación confiable,         UDP, TCP\n                       corrección de errores, Control\n                       de flujo, Establece, mantiene y\n                       finaliza comunicaciones\n3       RED            Direccionamiento lógico,        IP, RIP, ARP\n                       determinación de ruta\n2       Enlace de      Direccionamiento Físico,        ETHERNET, Frame\n        datos          Acceso al medio                 Relay, ATM\n1       Física         Codificación, Transmisión,      (Utp, Fibra", "topic": 0}, {"layer": 1, "page": 3, "text": "2.2 CAPAS DEL MODELO OSI, TCP/IP\n\n\n\n\nOSI                    TCP/IP       PROTOCOLOS\nAplicación,            Aplicación   TELNET, FTP, SNMP,\nPresentación, Sesión                TFTP, DNS, HTTP\nTransporte             Transporte   TCP, UDP\n\n\n\nRed                    Internet     ARP, IP,\nEnlace de datos        Física       Ethernet, Token Ring,\nFísica                              Frame relay, ATM", "topic": 0}, {"layer": 1, "page": 4, "text": "2.3 CAPA FISICA\n\n●\n    Primera capa más inferior.\n\n    Define las interfaces eléctrica y de temporización\n\n●\n\n\n    de la red.\n\n●\n    La Naturaleza establece límites en              las\n    capacidades de los medios físicos                de\n    transmisión.", "topic": 1}, {"layer": 1, "page": 5, "text": "2.3.1 BASE TEÓRICA DE\n          COMUNICACIÓN DE DATOS\n\n●\n    Es posible transmitir información variando\n    algunas propiedades eléctricas: V, I aplicadas a\n    un medio.", "topic": 1}, {"layer": 1, "page": 6, "text": "2.3.2 ANÁLISIS DE FORIER\n\n\n                    ●\n                        Juan Bautista Fourier probó\n                        que       cualquier     función\n                        periódica g(t) se puede\n\n                        construir     sumando      una\n                        cantidad,         posiblemente\n                        infinita, de senos y cosenos:\nFrancia 1768-1830", "topic": 1}, {"layer": 1, "page": 7, "text": "2.3.2.1 SERIES DE FOURIER\n               Serie de Fourier\n\n\n\n\n●\n    f = 1/T frecuencia fundamental. Frecuencia de\n    la primera armónica.\n●\n    Frecuencias de las demás armónicas son\n    múltiplos enteros de f.", "topic": 1}, {"layer": 1, "page": 8, "text": "2.3.2.2 ANÁLISIS DE FORIER\n\n●\n    an, bn: amplitudes de los senos y cosenos de los\n    n-ésimos términos armónicos.\n●\n    Para reconstruir g(t) se deben conocer la f\n\n    fundamental y las amplitudes ai y bi.\n●\n    El período T de g(t) es igual al período de la\n    frecuencia fundamental.", "topic": 1}, {"layer": 1, "page": 9, "text": "2.3.2 ANÁLISIS DE FORIER\n\n\n\n\nEn donde La amplitud c se calcula integrando\ndirectamente de 0 a T.", "topic": 1}, {"layer": 1, "page": 10, "text": "2.3.2 ANÁLISIS DE FORIER\n\n●   En la vida real, los sistemas de transmisión\n    disminuyen los componentes de Fourier en\n    diferente grado, causando distorsión.\n    Por lo general, las amplitudes se transmiten\n\n●\n\n    sin distorsión desde 0 hasta una cierta\n    frecuencia llamada frecuencia de corte fc.\n●   Las frecuencias mayores a fc se atenúan.", "topic": 1}, {"layer": 1, "page": 11, "text": "2.3.2 ANÁLISIS DE FORIER\n\n    Ancho de banda absoluto o espectro: rango de\n    frecuencias de la señal.\n●\n    El ancho de banda es propiedad física del medio\n    de transmisión. Depende del material, grosor,\n\n    longitud, construcción.\n●\n    Todo sistema de transmisión tiene una limitada\n    banda de frecuencias.\n●\n    Esto limita la tasa de datos a ser transportada.\n●\n    Otras veces se usan filtros para limitar el ancho\n    de banda a cada cliente: sistema telefónico (3100\n    Hz).", "topic": 1}, {"layer": 1, "page": 12, "text": "2.4 MEDIOS DE TRASMISIÓN\n\n\nLa comunicación se lleva a través de la propagación\nde ondas electromagnéticas.\nLas ondas electromagnéticas se pueden transmitir\n\na través de un medio físico sólido, o a través del\nespacio abierto.", "topic": 2}, {"layer": 1, "page": 13, "text": "2.4.1 CARACTERISTICAS DE UN\n          MEDIO DE TRANSMISIÓN\n\n●\n    Ancho de banda\n●\n    Retardo\n\n\n●\n    Facilidad de instalación y mantenimiento\n●\n    Costo\n●\n    Vida útil", "topic": 2}, {"layer": 1, "page": 14, "text": "2.4.1 Tipos de Medios guiados\n\n–   Cable coaxial\n–   Par trenzado.\n     ●\n         UTP\n     ●\n         STP\n\n– Fibra óptica.", "topic": 2}, {"layer": 1, "page": 15, "text": "Cable\n                 Specifications\n\n\n\n\n●\n    Cables have different specifications", "topic": 2}, {"layer": 1, "page": 16, "text": "Coaxial Cable", "topic": 2}, {"layer": 1, "page": 17, "text": "Coaxial Cable\n\n\n\n●\n    Advantages:\n    – Requires fewer repeaters than twisted pair\n    – Less expensive than fiber\n    – It has been used for many years for many types of\n       data communication, including cable television\n●\n    Disadvantages:\n    – More expensive and more difficult to install than\n       twisted pair\n    – Needs more room in wiring ducts than twisted pair", "topic": 2}, {"layer": 1, "page": 18, "text": "Coaxial Cable TIPOS\n\n 50 ohmios: transmisión digital.\n 75 ohmios:\n   transmisión analógica,\n   TV cable,\n   Internet por cable (cable módem),\n   MAN.\n\n\n\n Fue muy usado en líneas telefónicas de larga\n  distancia. Hoy se usa fibra óptica.", "topic": 2}, {"layer": 1, "page": 19, "text": "Unshielded Twisted Pair (UTP)\n\n\n\n\n Unshielded twisted-pair cable (UTP) is a four-pair wire\n  medium used in a variety of networks.\n TIA/EIA-568-A/B contains specifications governing cable\n  performance.\n RJ-45 connector\n When communication occurs, the signal that is transmitted by\n  the source needs to be understood by the destination.", "topic": 2}, {"layer": 1, "page": 20, "text": "Shielded Twisted Pair (STP and ScTP)\n    STP – Shielded Twisted Pair                   ScTP 0 FTP – Screened Twisted\n                                                  Pair\n\n\n\n\n●\n     Shielded twisted-pair cable (STP) combines the techniques of\n     shielding, cancellation, and twisting of wires.\n      – Each pair of wires is wrapped in metallic foil.\n      – The four pairs of wires are wrapped in an overall metallic braid or foil.\n●\n     Screened UTP (ScTP), also known as Foil Twisted Pair (FTP).\n      – ScTP is essentially UTP wrapped in a metallic foil shield, or screen.", "topic": 2}, {"layer": 1, "page": 21, "text": "ANCHO DE BANDA DE PAR TRENZAD0\n Categoría    Descripción      Ancho de\n                                banda\n                                 MHz\n             Líneas\n    3                            16\n             telefónicas\n             1988\n             Más trenzas.\n     5\n             Menor               100\n    5e       Interferencias.\n             Mejor calidad.\n    6                            200\n    7                            600", "topic": 2}, {"layer": 1, "page": 22, "text": "Categorías y clases del par trenzado\n            Category    Category    Category   Category    Category\n            3 Class C   5 Class D      5E      6 Class E   7 Class F\n\n\n\n\nBandwidt    16 MHz      100 MHz     100 MHz    200 MHz     600 MHz\nh\n\n\n\nCable       UTP         UTP/FTP     UTP/FTP    UTP/FTP     SSTP\nType\n\n\n\nLink Cost   0.7         1           1.2        1.5         2.2\n(Cat 5\n=1)", "topic": 2}, {"layer": 1, "page": 23, "text": "Fiber Optic\n\n Tasa de datos sobre 50 Mil Gbps. 50 Tbps.\n\n Límite práctico de señalización actual es 10\n  Gbps (100 Gbps en laboratorio).\n   Debido a la incapacidad de convertir con más rapidez\n    las señales eléctricas a ópticas.\n Desde   este punto de vista, las computadoras\n  son extremadamente lentas.\n   La comunicación le ganó a la computación.", "topic": 3}, {"layer": 1, "page": 24, "text": "Fiber Optic componentes\n\n Medio de transmisión: fibra de vidrio ultra delgada.\n\n Detector: genera pulso eléctrico al incidir luz en él.\n\n    Pulso de luz: bit 1,\n\n    Ausencia de luz: bit 0.\n\n Sistema   de transmisión unidireccional: fuente de\n  luz en el un extremo de la fibra, detector en el otro.", "topic": 3}, {"layer": 1, "page": 25, "text": "Fiber Optic\n\n La propagación del rayo de luz confinada dentro\n\n  de la fibra debido a la ley física de la refracción.\n   Refracción: Cambio de dirección de un haz de luz al\n\n    pasar de un medio físico a otro.", "topic": 3}, {"layer": 1, "page": 26, "text": "Fiber Optic\n\n\n\n\nÍndice de refracción de un medio n = c/v\nc: velocidad de la luz en el vacío\nv: velocidad de la luz del medio", "topic": 3}, {"layer": 1, "page": 27, "text": "Fiber Optic", "topic": 3}, {"layer": 1, "page": 28, "text": "Fiber Optic\n\n Fibras con grosor mayor a           cierto   valor,\n  conducen más de un haz de luz.\n Cada haz rebotará con ángulos diferentes o\n  modos diferentes.\n   Fibras con estas características se llaman fibras\n    multimodo.", "topic": 3}, {"layer": 1, "page": 29, "text": "Fiber Optic\n\n Guía de onda: diámetro se reduce a unas\n cuantas λ.\n   El haz se propaga sin reflejarse en los límites de la\n    fibra.\n   Fibras con esta propiedad se denominan monomodo.\n\n Para distancias mucho más largas: 100 Km a 50\n Gbps.", "topic": 3}, {"layer": 1, "page": 30, "text": "Fiber Optic\n\n La fibra se fabrica de silicio. Se encuentra en la\n  arena, material de muy bajo costo. Hay en\n  cantidades ilimitadas.\n Fibra tan transparente como el aire.", "topic": 3}, {"layer": 1, "page": 31, "text": "Fiber Optic", "topic": 3}, {"layer": 1, "page": 32, "text": "Fiber Optic Cabling", "topic": 3}, {"layer": 1, "page": 33, "text": "ST and SC Connectors\n\n\n\n\n●\n  The type of connector most commonly used with\n  multimode fiber is the Subscriber Connector (SC\n  connector); LC connector smaller than the sc , FC\n  Replacement by ST Y SC\n●\n  On single-mode fiber, the Straight Tip (ST)\n  connector is frequently used. MT-Array (array de\n  fiber)", "topic": 3}, {"layer": 1, "page": 34, "text": "Fiber Optic Patch Panel", "topic": 3}, {"layer": 1, "page": 35, "text": "Tres formas de conectar fibras\n1.-Conectores. Pérdida de LUZ es del 10 al 20% de\nluz.\n2.- Empalme mecánico. Alineación y sujeción.\nPérdida de luz es del 10%.\n3.-Fusión. Sólo se produce atenuación\nCortes especiales.\nUso de microscopio.\nFundición con arco eléctrico.\nCasi tan bueno como una fibra.\n\n\nDefecto: ocurren reflexiones en los empalmes.", "topic": 3}, {"layer": 1, "page": 36, "text": "Características de transmisión\nLa FO, se fabrica a partir de la arena, Actúa como guía de\nonda para 1014 a 1015 Hz\n   Infrarrojo y espectro visible\nLED (Light Emitting Diode)\n –   Más barato\n –   Opera a mayores temperaturas\n –   Tiempo de vida medio superior\nInjection Laser Diode (ILD)\n –   Más eficiente, mayor sensibilidad\n –   Mayor tasa de datos\nMultiplexión por división de λ WDM", "topic": 3}, {"layer": 1, "page": 37, "text": "Fuentes de luz", "topic": 3}, {"layer": 1, "page": 38, "text": "Fuentes de luz\n\n●\n    El receptor es un fotodíodo, que emite un pulso\n    eléctrico cuando le golpea la luz.\n●\n    Tiempo de respuesta o sensibilidad = 1nseg.\n    –   Limita la tasa de datos a 100 Gbps.\n●\n    Ruido térmico también es problema. La señal\n    de luz tiene que elevar el nivel de potencia para\n    que pueda ser detectada.", "topic": 3}, {"layer": 1, "page": 39, "text": "REDES DE FIBRA ÓPTICA\n\n●\n    Usos de la fibra óptica:\n    – LANs,\n    – Transmisiones de largo alcance.\n●\n  Conectarse a la fibra óptica es más complejo\n  que a una Ethernet.\n●\n  Topologías de una LAN de fibra óptica:\n    – Anillo: Colección de enlaces punto a punto.\n    – Estrella.", "topic": 3}, {"layer": 1, "page": 40, "text": "Ventajas de la fibra óptica respecto al cobre\n●\n  Anchos de banda mucho mayores al cobre.\n●\n  Baja atenuación.\n●\n  Inmunidad contra:\n   – Sobrecargas de energía,\n   – interferencia electromagnética,\n   – sustancias corrosivas.\n●\n  Delgada y liviana. Importante para las PSTN.\n●\n  Bajo costo de instalación.\n●\n  No hay fugas de luz.\n●\n  Difícil intervenirlas.\n●\n  Seguridad contra intrusos y espías.", "topic": 3}, {"layer": 1, "page": 41, "text": "Ventajas de la fibra óptica respecto al cobre\n●\n    Es mucho mas ligera que el cobre(Mil pares de\n    1 km de longitud peso 8000 kg, dos Fibras\n    tienen mas capacidad y solo pesan 100 kg).", "topic": 3}, {"layer": 1, "page": 42, "text": "Aplicaciones de la Fibra óptica\n●\n    Troncales de gran recorrido\n●\n    Troncales MAN\n●\n    Última milla, bucle del abonado, bucle\n    local(conexión del ultimo kilómetro), bucle de\n    suscriptor, redes de acceso.\n●\n    LANs", "topic": 3}, {"layer": 1, "page": 43, "text": "Debilidades de la Fibra óptica\n\n●\n    Tecnología aun poco familiar. Requiere\n    habilidades que muchos ingenieros carecen.\n●\n    Muy delicada. Se puede doblar o romper.\n●\n    Transmisión unidireccional. La comunicación\n    duplex requiere dos fibras o dos bandas de\n    frecuencia en una fibra.\n●\n    Interfaces de fibra más caras que las eléctricas.", "topic": 3}, {"layer": 1, "page": 44, "text": "Espectro electromagnético de los medios\nguiados", "topic": 3}, {"layer": 1, "page": 45, "text": "Lineas Eléctricas\n●\n    El uso de las lineas eléctricas (Transportan energía\n    eléctrica en las casas, y el cableado eléctrico distribuye\n    la energía a los tomas de corriente)\n●\n    Estudios recientes tratan de transmitir señales de datos\n    por medio del cableado eléctrico, formando una LAN con\n    acceso de internet de banda ancha.\n●\n    Se puede transmitir a 100 Mbps teniendo esquemas que\n    resisten a frecuencias dañadas y ráfaga de errores", "topic": 4}, {"layer": 1, "page": 46, "text": "Lineas Eléctricas\n●\n    Desventajas\n●\n    Las señales eléctricas se transmiten de 50 a 60 Hz, y el\n    cableado atenúa a las señales con frecuencias mucho\n    mas altas (MHz) eléctricos.\n●\n    Cuando se prende o se apaga un electrodoméstico se\n    crea ruidos", "topic": 4}, {"layer": 1, "page": 47, "text": "2.5 MEDIOS DE TRANSMISION NO\n            GUIADOS\n\n●\n    En el futuro sólo habrían dos clases de\n    comunicaciones:\n    – Fibra óptica para los dispositivos fijos.\n    – Inalámbrica para:\n        ●\n            laptops,\n        ●\n            PDAs (Personal Digital Assistant),\n        ●\n            Dispositivos fijos de difícil acceso.\n●\n    Las comunicaciones inalámbricas se iniciaron\n    en las islas de Hawai. (Largos tramos de\n    Océano , separan a los usuarios de un centro\n    de computo)", "topic": 5}, {"layer": 1, "page": 48, "text": "Espectro electromagnético\n●\n    Electrones en movimiento producen ondas\n    electromagnéticas que se propagan por el\n    espacio.\n●\n    El físico británico nacido en Edimburgo James\n    Maxwell las modeló matemáticamente en 1865.\n●\n    El físico judío-alemán nacido en Hamburgo\n    Henrich Hertz las experimentó en 1887.", "topic": 5}, {"layer": 1, "page": 49, "text": "Espectro electromagnético\n●\n    El número de oscilaciones por segundo de una\n    onda es la frecuencia y se mide en Hz.\n●\n    La distancia entre dos máximos o dos mínimos\n    se llama longitud de onda se lo denota por\n    lambda (λ); λ.f = c (velocidad de la luz)\n●\n    Al conectar una antena del tamaño apropiado a\n    un circuito eléctrico, la ondas electromagnéticas\n    se pueden difundir de manera eficiente y el\n    receptor las puede captar a cierta distancia\n    “Principio de las comunicaciones Inalámbricas”", "topic": 5}, {"layer": 1, "page": 50, "text": "●\n    Una      antena    puede     difundir   ondas\n    electromagnéticas, y éstas ser captadas por un\n    receptor.\n    –   Principio físico de las comunicaciones inalámbricas.\n●\n    En el vacío, las ondas electromagnéticas viajan\n    a la misma velocidad de la luz(c), independiente\n    de f.", "topic": 5}, {"layer": 1, "page": 51, "text": "TRANSMISION NO GUIADA\n●\n    Ondas electromagnéticas, que pueden recorrer el\n    vacío del espacio exterior y medios como el aire.\n●\n    No necesitan un medio físico para propagarse.\n●\n    Muy versátil para el desarrollo de redes.\n●\n     La aplicación más común de las comunicaciones de\n    datos corresponde a los usuarios móviles.\n●\n    Cualquier persona o elemento que necesite\n    comunicar datos a través de una red sin las\n    limitaciones de la FO o el cobre .", "topic": 5}, {"layer": 1, "page": 52, "text": "Trasmisión inalámbrico\n•   Espectro Electromagnético\n•   Transmisión de Radio\n•   Transmisión de Microonda\n•   Señales Infrarrojas\n•   Transmisión Señales de Luz", "topic": 5}, {"layer": 1, "page": 53, "text": "Frecuencias          de      transmisión\n         inalámbrica\n●   30MHz a 1GHz\n    – Broadcast de radio (difusión)\n    – Omnidireccional\n●   2GHz a 40GHz\n    – Microonda\n    – Alta direccionalidad\n    – Enlaces punto a punto\n    – Satélite\n●   3 x 1011 to 2 x 1014\n    –   Infrarrojo", "topic": 5}, {"layer": 1, "page": 54, "text": "Espectro electromagnético", "topic": 5}, {"layer": 1, "page": 55, "text": " Son nombres de ITU (Unión Internacional de\n Telecomunicaciones).\n   SHF supremamente alta.\n   EHF extremadamente alta.\n   THF tremendamente alta.\n\n Sepuede transmitir información modulando la\n amplitud, frecuencia o fase de las ondas.", "topic": 5}, {"layer": 1, "page": 56, "text": "RADIO TRANSMISIÓN\n 10 KHz – 100 MHz (108 Hz)\n\n Son relativamente fáciles de generar.\n\n Viajan distancias largas.\n\n Penetran paredes (en bajas frecuencias).\n\n Omnidireccionales.\n\n No es necesario línea de vista y alineación entre\n  el transmisor y receptor.", "topic": 5}, {"layer": 1, "page": 57, "text": "RADIO TRANSMISIÓN\n\n\n\n\na) Bandas VLF, LF, MF y las señales de radio\n   siguen la curvatura de la tierra. (1000 km)\n   (AM)\nb) En la banda HF y VHF, rebotan en la\n   ionosfera. (Rodean la tierra de 100 a 500 km)\n   Radio aficionados", "topic": 5}, {"layer": 1, "page": 58, "text": "RADIO TRANSMISIÓN\n En las bandas desde VLF a MF las ondas\n siguen la curvatura de la Tierra.\n   Se pueden detectar a 1.000 Km.\n\n   Característica usada por las emisoras de radio AM.\n\n Las ondas de HF y VHF son absorbidas por el\n suelo.\n   Si alcanzan la ionosfera (100 a 500Km) se refractan y\n    regresan a la tierra.", "topic": 5}, {"layer": 1, "page": 59, "text": "RADIO TRANSMISIÓN", "topic": 5}, {"layer": 1, "page": 60, "text": "RADIO TRANSMISIÓN\n\n A bajas frecuencias:\n\n   las ondas cruzan bien casi cualquier obstáculo.\n\n A frecuencias altas:\n\n   las ondas viajan en línea recta,\n\n   rebotan en los obstáculos\n\n   son absorbidas por la lluvia.", "topic": 5}, {"layer": 1, "page": 61, "text": "RADIO TRANSMISIÓN\n En   todas las frecuencias, las ondas son\n interferidas por el ruido de los motores.\n   El oído humano capta ondas de hasta 20 Khz.\n\n Todos los gobiernos reglamentan el uso del\n espectro.", "topic": 5}, {"layer": 1, "page": 62, "text": "TRANSMISIÓN POR MICROONDAS\n Se  consideran desde 100 MHz a 100 GHz\n  (108Hz – 1011Hz)\n Las ondas viajan en línea recta.\n No atraviesan muy bien edificios.\n Se puede enfocar un haz estrecho con antena\n  parabólica, impidiendo la interferencia.\n Telefonía celular: 850 MHz – 1.900 MHz\n Horno de microondas: 4G Hz.", "topic": 5}, {"layer": 1, "page": 63, "text": "TRANSMISIÓN POR MICROONDAS\n\n Se   necesitan repetidores periódicos. Ya que\n  estar demasiados separadas la tierra se\n  interpondrá\n Mientras más altas son las torres más\n  separadas pueden estar.\n Con torres de 100 m de altura las torres pueden\n  estar 80 Km separadas.\n A 4 GHz las ondas son absorbidas por el agua.\n   Cualidad  aprovechada por hornos de microondas.\n    Pero para las comunicaciones es un problema.", "topic": 5}, {"layer": 1, "page": 64, "text": "Políticas del Espectro Electromagnético\n\n Para evitar el caos, hay acuerdos nacionales e\n  internacionales en cuanto quién puede usar\n  ciertas frecuencias.", "topic": 5}, {"layer": 1, "page": 65, "text": "Políticas del Espectro Electromagnético\n Los    gobiernos nacionales asignan espectros\n para:\n   La radio AM y FM\n   Televisión\n   Teléfonos celulares\n   Policía\n   Marina\n   Navegación\n   Milicia\n   Entidades de gobierno, etc.", "topic": 5}, {"layer": 1, "page": 66, "text": "Políticas del Espectro Electromagnético\n A      nivel   mundial,   ITU-R    (sector    de\n  radiocomunicaciones) coordina esta asignación\n  facilitando la fabricación de dispositivos de\n  comunicación.\n FCC (Federal Communications Commission) se\n  encarga de asignar las frecuencias en los EUA y\n  ha       rechazado     ocasionalmente     dichas\n  recomendaciones.\n En Ecuador ¿Quien Regula y controla el\n  espectro electromagnético?", "topic": 5}, {"layer": 1, "page": 67, "text": "Concesión del espectro\n\n Las empresas portadoras -telefónicas celulares-\n  concursan ofreciendo el servicio que mejor se\n  ajuste a los intereses públicos.\n   Los funcionarios de gobierno deciden a quien dar. Se\n    presta para sobornos.\n Otra forma es sortear entre las empresas.\n\n Otra es subastar el espectro al mejor postor.", "topic": 5}, {"layer": 1, "page": 68, "text": "Bandas ISM Industrial, Scientific and\n                 Medical\n Otra forma de asignar frecuencias es no asignar\n\n  por completo.\n Política aplicada con las bandas ISM\n\n Se deja que todos transmitan a voluntad.\n\n Se    regula la potencia usada tal que las\n  estaciones tengan una rango que no se\n  interfieran entre sí.", "topic": 5}, {"layer": 1, "page": 69, "text": "Bandas ISM Industrial, Scientific and\n                 Medical\n Estas bandas no requieren autorización.\n Aplicaciones:\n   Redes LAN 802.11\n   Teléfonos inalámbricos\n   Ratones inalámbricos, etc.\n   Dispositivos inalámbricos para abrir puertas\n   Juguetes a control remoto", "topic": 5}, {"layer": 1, "page": 70, "text": "Bandas ISM Industrial, Scientific and\n                   Medical\n\n\n\n\n902-928 MHz Está saturado (Primeras versiones 802.11 )\n2.4 GHz      LAN 802.3, Bluetooth, 802.11 b/g, PAN\ninalámbricas\n5.7 GHz      No explotada, equipos caros, pero ganando\npopularidad (banda de los 5 Ghz)", "topic": 5}, {"layer": 1, "page": 71, "text": "Concesión del espectro\n\nLa FCC (Comisión Federal de Comunicaciones)libera los\nespacios en blando alrededor de los 700 MHz, a partir de\nla transición de la televisión analógica a digital en el\n2009.\nLa FCC libera también la banda de los 60 GHz (57 a 64\nGHz debajo de radiación infrarroja) utilizadas en redes\nde alta velocidad pero corto alcance, no se propagan a\nlarga distancia porque son absorbidas por el oxígeno y\nson aplicadas en transmisiones de Tv de alta definición.", "topic": 5}, {"layer": 1, "page": 72, "text": "Transmisión Infrarroja\n1012Hz – 1014Hz\n Para comunicación de corto alcance.\n\n WLANs, Controles remotos de TVs, DVDs, etc.\n\n Económicos, direccionales y fáciles de construir.\n\n No atraviesan objetos sólidos. Son mas seguras\n  que las ondas de radio\n Conforme  se pasa de las ondas de radio de\n  onda larga hacia la luz visible, las ondas se\n  comportan cada vez más como la luz y menos\n  como radio.", "topic": 6}, {"layer": 1, "page": 73, "text": "Transmisión Infrarroja\n\n No hay necesidad de licencia del gobierno.\n El estándar de infrarrojo es IrDa(Asociación de\n  datos por Infrarrojo)", "topic": 6}, {"layer": 1, "page": 74, "text": "Transmisión por ondas de luz\n\n También conocida como señalización óptica sin\n  guía u Óptica de espacio libre.\n LANs de dos edificios pueden conectarse por\n  medio de láser montados en sus azoteas.\n La comunicación es simplex unidireccional\n Gran ancho de banda.\n Costo muy bajo.\n Relativamente fácil de instalar.\n No requiere licencia.", "topic": 6}, {"layer": 1, "page": 75, "text": "Transmisión por ondas de luz\n\n Haces muy estrechos.\n Apuntar un rayo láser de 1 mm. a un blanco del\n  tamaño de la punta de un alfiler a 2 Km de\n  distancia requiere de mucha puntería.\n No penetran la lluvia ni la niebla densa.\n No Funciona bien en días soleados.", "topic": 6}, {"layer": 1, "page": 76, "text": "Transmisión por ondas de luz", "topic": 6}, {"layer": 1, "page": 77, "text": "2.6 SATELITES DE\n            COMUNICACIONES\n En  los 50s se intentó establecer sistemas de\n  comunicación mediante el rebote de señales en\n  globos climáticos(Globos meteorológicos), pero\n  sus señales eran muy débiles.\n La marina de los U.S. descubrió una especie de\n  globo climático en el cielo – la Luna- y desarrolló\n  un sistema de comunicación que rebotaba las\n  señales en ella.", "topic": 7}, {"layer": 1, "page": 78, "text": "2.6 SATELITES DE\n             COMUNICACIONES\n Luego vinieron los satélites artificiales.\n\n La principal diferencia con un satélite natural es\n  que amplifica la señal antes de reenviarla.\n Un   satélite artificial es     un    repetidor   de\n  microondas en el cielo.\n Tiene varios transponders. Se encargan de una\n  parte del espectro. Reciben la señal entrante, la\n  amplifican y la retransmiten en otra frecuencia. A\n  esto se lo conoce como Tubo doblado", "topic": 7}, {"layer": 1, "page": 79, "text": "2.6 SATELITES DE\n          COMUNICACIONES\n                      Los     haces de retorno\n                       pueden cubrir una fracción\n                       sustancial de la superficie\n                       terrestre.\n                      Kepler: el período orbital de\n                       un satélite varía según el\n                       radio de la órbita elevada a\n                       la 3/2.\n                      A más altura mayor es el\n  Johannes Kepler\nAlemania 1571-1630     período.", "topic": 7}, {"layer": 1, "page": 80, "text": "2.6 SATELITES DE\n            COMUNICACIONES\n A 35.800 Km sobre el nivel del mar, el período\n\n  es de 24 horas.\n   Órbita geoestacionaria u órbita Clarke.\n\n A 384.000 Km el período es cercano a un mes,\n\n  como es el caso de la Luna.", "topic": 7}, {"layer": 1, "page": 81, "text": "2.6 SATELITES DE\nCOMUNICACIONES", "topic": 7}, {"layer": 1, "page": 82, "text": "2.6.1 SATELITES\n          GEOESTACIONARIOS\n Ideado por el escritor de ciencia ficción Arthur C.\n  Clarke en 1945.\n Orbitan a una altura de 35.800 Km.\n Ubicados en la zona ecuatorial.\n No es necesario rastrearlos.\n GEO= Orbita Terrestre Geoestacionaria", "topic": 7}, {"layer": 1, "page": 83, "text": "2.6.1 SATELITES GEOESTACIONARIOS\n\n            Arthur C. Clarke\n            Gran Bretaña 1917 –\n            Novela:\n            2001: Una odisea espacial (1968)\n\n            Leyes\n            La única manera de descubrir los\n              límites de lo posible es\n              aventurarse hacia lo imposible.\n\n            Cualquier        tecnología      lo\n              suficientemente avanzada      es\n              indistinguible de la magia.", "topic": 7}, {"layer": 1, "page": 84, "text": "2.6.1 SATELITES\n          GEOESTACIONARIOS\n Clarke pensó que los satélites no eran prácticos\n  por no poder poner en órbita amplificadores de\n  tubos catódicos frágiles que consumían gran\n  cantidad de energía.\n La invención del transistor (Laboratorios Bell) en\n  1948 cambió las cosas.", "topic": 7}, {"layer": 1, "page": 85, "text": "2.6.1 SATELITES GEOESTACIONARIOS\n\n\n\n\n                     Telstar 1962\n\n\n\n\nSputnik I 1957", "topic": 7}, {"layer": 1, "page": 86, "text": "2.6.1 SATELITES\n           GEOESTACIONARIOS\n ITU asigna la posición orbital de cada satélite.\n Los países demandan sus posiciones orbitales.\n Los satélites pesan hasta 5.000 Kg y consumen\n  varios Kw.\n La gravedad del Sol y la Luna desplaza a los\n  satélites de sus órbitas.\n    Se contrarresta con motores integrados al satélite.", "topic": 7}, {"layer": 1, "page": 87, "text": "2.6.1 SATELITES\n           GEOESTACIONARIOS\n ITU asigna bandas de frecuencia a los usuarios\n  de satélites.\n La banda C está sobresaturada ya que se usa\n  también en microonda terrestre.\n Con la banda Ku es posible separar los satélites\n  a menos de un grado.", "topic": 7}, {"layer": 1, "page": 88, "text": "2.6.1 SATELITES\nGEOESTACIONARIOS", "topic": 7}, {"layer": 1, "page": 89, "text": "2.6.1 SATELITES\n          GEOESTACIONARIOS\n El haz de los satélites geoestacionarios pueden\n\n  abarcar hasta 1/3 de la superficie de la tierra\n  (huella o footprint).\n Un  satélite puede también emitir a la Tierra\n  múltiples haces reducidos que abarquen\n  pequeñas zonas geográficas.", "topic": 7}, {"layer": 1, "page": 90, "text": "2.6.1.1 VSAT\n Son microestaciones de bajo costo.\n Las antenas son de 1 m o menos, frente a los 10\n  m de GEO.\n Consumen alrededor de 1 watt de potencia.\n Tasa uplink 1 Mbps y downlink varios Mbps.\n Usa la televisión de difusión directa por satélite\n  para transmisión unidireccional.\n La comunicación entre 2 VSATs se hace a través\n  de un hub. Hay más retardo (540 ms).\n En las microondas 3 μseg y fibra optica 5 μseg", "topic": 7}, {"layer": 1, "page": 91, "text": "2.6.1.1 VSAT", "topic": 7}, {"layer": 1, "page": 92, "text": "2.6.1.1 Antena parabólica VSAT: bandas C,\n                 Ku, Ka", "topic": 7}, {"layer": 1, "page": 93, "text": "", "topic": 7}, {"layer": 1, "page": 94, "text": "2.6.1.1 VSAT\n\n Las VSATs tienen futuro en las zonas rurales.\n Más de la mitad de la población del mundo vive\n  a una hora de distancia del teléfono más\n  cercano.\n Tender redes eléctricas para miles de pequeñas\n  poblaciones excede el presupuesto de la\n  mayoría de los gobiernos del tercer mundo.\n Sí es factible la instalación de antenas VSATs\n  alimentadas por celdas solares.", "topic": 7}, {"layer": 1, "page": 95, "text": "2.6.1.1 VSAT\n\n Propiedad  importante de los satélites: Son\n  esencialmente medios de difusión.\n   Cuesta  igual enviar a una estación o a miles de\n    estaciones dentro de la footprint del transponder.\n Pero los satélites son un desastre en seguridad\n  y privacidad,\n   Es esencial la encriptación.", "topic": 7}, {"layer": 1, "page": 96, "text": "2.6.2 Satélites de Orbita Terrestre\n                Media\n Se  encuentran entre los cinturones de Van\n  Allen.\n Tardan seis horas dando la vuelta a la Tierra.\n\n Es necesario rastrearlos.\n\n Ya que están más cerca de la Tierra, tienen\n  una footprint más pequeña.\n Se requieren transmisores menos potentes.\n\n Aplicación de MEO son los 30 satélites GPS.\n\n Se usan en los sistemas de navegación", "topic": 7}, {"layer": 1, "page": 97, "text": "2.6.2 Cinturones de Van Allen\n\n\n\n\nZonas de la magnetosfera.\nConcentración de protones y electrones\n2 Anillos toroidales. Uno interior (1.000 y 5.000 km.)\notro exterior (15.000 y 20.000 km)", "topic": 7}, {"layer": 1, "page": 98, "text": "2.6.3 Satélites de Orbita Terrestre Baja\n Se encuentran a distancias mas bajas\n  menores a los 5000 km\n Utilizados para el servicio de voz, Aviación,\n  industrias marítimas y de explotación\n  petroleras personas que viajan por el mundo\n  sin infraestructura de telecomunicaciones\n El retardo es de 1 a 7 ms.", "topic": 7}, {"layer": 1, "page": 99, "text": "2.6.3 Satélites de Orbita Terrestre Baja\n\n Tres ejemplos:\n   Iridium\n   Globalstar\n   CubeSat", "topic": 7}, {"layer": 1, "page": 100, "text": "2.6.3 IRIDIUM\n\n En 1990, Motorola solicitó a FCC permiso para\n  lanzar 77 satélites LEO.\n El elemento 77 de la tabla periódica es el Iridio\n La idea era que tan pronto como un satélite se\n  perdiera de vista, otro lo reemplace.\n El servicio empezó en 1998.\n Pero la demanda comercial de teléfonos por\n  satélites fue insignificante, en parte debido a la\n  expansión de la telefonía celular.", "topic": 7}, {"layer": 1, "page": 101, "text": "2.6.3 IRIDIUM", "topic": 7}, {"layer": 1, "page": 102, "text": "2.6.3 IRIDIUM", "topic": 7}, {"layer": 1, "page": 103, "text": "2.6.3 IRIDIUM\n\n La    telefonía    celular   había   crecido\n  espectacularmente\n El proyecto Iridium, de $ 5.000 millones\n  quebró en menos de un año.\n Fue uno de los fracasos corporativos más\n  espectacular de la historia.\n Luego alguien lo compró en $ 25 millones en\n  una especie de venta de garaje.", "topic": 7}, {"layer": 1, "page": 104, "text": "2.6.3 IRIDIUM\n\n Iridium da servicio en todo el mundo a través de\n  dispositivos que se comunican directamente con\n  los satélites.\n Servicios:\n   voz,\n   datos,\n   búsqueda de personas,\n   fax,\n   navegación, en tierra, mar y aire.", "topic": 7}, {"layer": 1, "page": 105, "text": "2.6.3 IRIDIUM\n\n Clientes de Iridium:\n   industria marítima,\n   aviación,\n   exploración petrolera,\n   periodistas,\n   personas que viajan por desiertos, montañas, selvas.\n   Ciertos países del tercer mundo.", "topic": 7}, {"layer": 1, "page": 106, "text": "2.6.3 IRIDIUM", "topic": 7}, {"layer": 1, "page": 107, "text": "2.6.3 IRIDIUM\n\n Los satélites están a 750 Km de altura.\n\n Recorren órbitas polares circulares.\n\n Hay   un satélite en cada 32 grados de latitud\n  (vertical).\n Toda la Tierra se cubre con seis collares.\n\n Hay    varios representantes comerciales de\n  Iridium en Ecuador: Quito, Guayaquil y Manta.", "topic": 7}, {"layer": 1, "page": 108, "text": "2.6.3 Globalstar\n\n Es un diseño alterno para Iridium.\n\n Se basa en 48 satélites LEO.\n\n Iridium     retransmite las llamadas de satélite a\n  satélite.\n Globalstar     utiliza un diseño de “tubo doblado”\n  tradicional.", "topic": 7}, {"layer": 1, "page": 109, "text": "2.6.3 Globalstar", "topic": 7}, {"layer": 1, "page": 110, "text": "2.6.3 CubeSat\n\n Son Satélites en miniatura en unidades de cubo\n    (10X10X10 cm), cada uno pesa a lo mucho 1\n    Kg, en comparación con 5000 kg de los satélites\n    normales.\n    Los académicos Cal Poly y Stanford definen el\n    estandar en 1999\n La     mayoría de ellos se comunican con\n    estaciones terrestres en las bandas de UHF y\n    VHF", "topic": 7}, {"layer": 2, "page": 1, "text": "FACULTAD DE LA ENERGÍA LAS\nINDUSTRIAS Y LOS RECURSOS\nNATURALES NO RENOVABLES\n\nCARRERA EN COMPUTACIÓN\n\nFUNDAMENTOS DE REDES\n  DE COMUNICACIONES\n\n    CAPA DOS Y TRES", "topic": 8}, {"layer": 2, "page": 2, "text": "Capa de enlace de datos\n     y tecnologías", "topic": 8}, {"layer": 2, "page": 3, "text": "Funciones de la Capa De enlace de\n              datos\n●\n    Desempeña funciones específicas como:\n    – Proporcionar una interfaz de servicio bien\n      definida para la capa de red.\n    – Determinar la manera como los bits se\n      agrupan en tramas, suministrando tránsito\n      de datos confiable a través del enlace físico\n      utilizando las direcciones MAC.\n    – Manejar los errores de transmisión y\n    – Regular el flujo de tramas para que los\n      receptores lentos no sean saturados por\n      transmisores rápidos.", "topic": 8}, {"layer": 2, "page": 4, "text": "Funciones de la Capa De\n              enlace de datos\n●\n    Para realizar las funciones, la capa 2 encapsula\n    en tramas los paquetes de la capa 3.\n●\n    Trama:\n\n    –   Encabezado.\n    –   Carga útil para el paquete.\n    –   Final.\n●\n    Los controles de flujo y errores realiza la capa 2\n    y la capa 4.", "topic": 8}, {"layer": 2, "page": 5, "text": "Funciones de la Capa De\n    enlace de datos", "topic": 8}, {"layer": 2, "page": 6, "text": "Servicios de la Capa De\n         enlace de datos\n La capa de enlace se puede diseñar ofreciendo\n varios servicios:\n1.No orientado a la conexión sin confirmación de\n  recepción.\n\n2.No orientado a la conexión con confirmación de\n  recepción.\n3.Orientado a la conexión con confirmación de\n  recepción.", "topic": 8}, {"layer": 2, "page": 7, "text": "1.- Servicio no orientado a\n             la conexión sin\n       confirmación de recepción\n\n●\n    No se establece conexión de antemano.\n\n●\n    La     máquina     origen   envía     tramas\n    independientes a la máquina destino sin pedir\n    confirmación.\n●\n    Si se pierde una trama debido a ruido en la\n    línea, la capa 2 no lo detecta ni trata de\n    recuperarla.", "topic": 8}, {"layer": 2, "page": 8, "text": "●\n  Servicio apropiado con baja tasa de errores.\n●\n  Para aplicaciones de tiempo real.\n●\n    Adecuado para redes LAN.\n\n    – Ethernet da un servicio no orientado a la\n      conexión fiable.", "topic": 8}, {"layer": 2, "page": 9, "text": "Servicio no orientado a la\n       conexión con confirmación de\n                 recepción\n El emisor sabe si la trama ha llegado bien o no.\n\n Si no ha llegado, lo reenvía.\n\n\n Usado  en canales inestables como en redes\n  inalámbricas.\n En  canales confiables como fibra óptica, este\n  servicio es innecesario.", "topic": 8}, {"layer": 2, "page": 10, "text": "Servicio orientado a la\n           conexión con\n     confirmación de recepción\n Servicio confiable.\n\n Numeración de tramas para garantizar:\n\n\n   Se  reciben en el mismo orden en que fueron\n    enviadas.\n   Cada trama se recibe exactamente una vez.\n\n   Cada trama llega a su destino sin errores.", "topic": 8}, {"layer": 2, "page": 11, "text": " Se controla las tramas que han sido recibidas y\n\n  las que no.\n El SW de la capa 2 podría implementarse en un\n\n\n  chip de hardware.", "topic": 8}, {"layer": 2, "page": 12, "text": "", "topic": 8}, {"layer": 2, "page": 13, "text": "ENTRAMADO\n\n Métodos para indicar el inicio y fin de una trama:\n\n\n\n\n           \n               Conteo de Bytes.\n           \n               Byte Banderas, con relleno de Bytes.\n           \n               Bits Banderas con relleno de bits.\n           \n               Violación de codificación de la capa física.", "topic": 9}, {"layer": 2, "page": 14, "text": "CONTEO DE BYTES\n Se requiere un campo en el encabezado para\n\n  indicar el número de Bytes de la trama (longitud\n  de trama).\n\n Método casi no usado.", "topic": 9}, {"layer": 2, "page": 15, "text": "CONTEO DE BYTES", "topic": 9}, {"layer": 2, "page": 16, "text": "2.- BYTES BANDERAS\n     CON RELLENO DE BYTES\n Una trama inicia y termina con bytes especiales. (FLAG\n\n Dos   bytes señalan el inicio y fin.\n Cuando la bandera se asemeja a los datos se usa un byte\n\n\n\n  especial “ESC”\n Si el receptor pierde sincronía, puede esperar a la siguiente\n  bandera.\n El receptor quita las banderas byte para entregar los datos\n  en la capa de red, a esto se le denomina Relleno de Bytes", "topic": 9}, {"layer": 2, "page": 17, "text": "BYTES BANDERAS CON\n         RELLENO DE BYTES\n Una trama inicia y termina con bytes especiales. (FLAG\n\n Dos   bytes señalan el inicio y fin.\n Con datos binarios, puede ocurrir que el patrón de bits de la\n\n\n  bandera aparezca entre los datos.( se usa un byte especial “ESC”)\n Si el receptor pierde sincronía, puede esperar a la siguiente\n  bandera.\n El receptor quita las banderas byte para entregar los datos en la\n  capa de red, a esto se le denomina Relleno de Bytes", "topic": 9}, {"layer": 2, "page": 18, "text": "BYTES BANDERAS CON\n RELLENO DE BYTES", "topic": 9}, {"layer": 2, "page": 19, "text": "BYTES BANDERAS CON\n        RELLENO DE BYTES\n Desventaja:    esquema fuertemente atado a\n caracteres de 8 bits. No todos los códigos\n utilizan caracteres de 8 bits.\n\n Se desarrolló una nueva técnica que permite\n caracteres de tamaño arbitrario.", "topic": 9}, {"layer": 2, "page": 20, "text": "3.- BITS BANDERA CON CON\n            RELLENO DE BITS\n Tramas de datos con número arbitrario de bits.\n\n Códigos de caracteres con número arbitrario de\n  bits.\n\n Cada trama inicia y termina con 01111110.\n\n Si la capa 2 encuentra cinco 1s consecutivos en\n  los datos, inserta un 0.\n Si el receptor ve cinco 1s de entrada seguido de\n  un 0, extrae el bit 0 de relleno.", "topic": 9}, {"layer": 2, "page": 21, "text": "BITS DE RELLENO", "topic": 9}, {"layer": 2, "page": 22, "text": "3.- VIOLACIÓN DE CODIFICACIÓN DE LA\n                  CAPA FÍSICA\n Se utilizan señales reservadas para indicar el inicio y fin\n  de cada trama. Sin la necesidad de relleno de datos.\n Algunas   LANs representan los bits de datos usando\n\n\n  codificación Manchester.\nAlto – bajo: bit 1.\nBajo – alto: bit 0.\n Algunos protocolos de esta capa usan una combinación\n  de estos por seguridad. Ejemplo 802.11 utiliza un\n  preámbulo(72 bits) seguido de un campo de longitud\n  para localizar el fin de la trama.", "topic": 9}, {"layer": 2, "page": 23, "text": "Capa de Enlace de Datos", "topic": 9}, {"layer": 2, "page": 24, "text": "Implementaciones Prácticas\n●\n  Token Ring, FDDI y Ethernet. Todas especifican\n  aspectos de la Capa 2 (LLC control de enlace\n  lógico, denominación, entramado y MAC), así como\n  también aspectos de los componentes de\n  señalización y de medios de la Capa 1.\n●\n  Ethernet: topología de bus lógica y en estrella física\n  o en estrella extendida.\n●\n  Token Ring: topología de anillo lógica y una\n  topología física en estrella.\n●\n  FDDI: topología de anillo lógica y topología física de\n  anillo doble.", "topic": 9}, {"layer": 2, "page": 25, "text": "Entramado o Enmarcado de\n             Datos\n●\n  Para entregar servicios a la Capa de red, la\n  Capa de enlace de Datos debe utilizar los\n  servicios proporcionados por la Capa física.\n●\n  La capa 1 acepta un flujo de bits “en bruto” y lo\n  entrega al destino o intenta hacerlo y no\n  garantiza ausencia de errores.\n●\n  El # de bits recibidos puede ser mayor, menor o\n  igual que el # de bits transmitidos.\n●\n  Es responsabilidad de la Capa de enlace de\n  Datos detectar y corregir estos errores.", "topic": 9}, {"layer": 2, "page": 26, "text": "Entramado o Enmarcado de\n         Datos", "topic": 9}, {"layer": 2, "page": 27, "text": "Formato de Trama Genérica\n●\n    Es un concepto teórico, que ayuda a entender la\n    tecnología y las tramas (802.3, 802.5, FDDI), los\n    paquetes (IP) y los segmentos (TCP y UDP)\n    específicos.\n●\n    Tiene secciones llamadas campos formados por bytes\n     – campo de inicio de trama\n     – campos de dirección\n     – campo de longitud/tipo/control\n     – campo de datos\n     – campo de secuencia de verificación de trama\n     – campo de fin de trama", "topic": 9}, {"layer": 2, "page": 28, "text": "Tecnologías de la Capa 2", "topic": 10}, {"layer": 2, "page": 29, "text": "IEEE 802 Committees\n802.0 SEC\n802.1 High Level Interface (HILI)\n802.2 Logical Link Control (LLC)\n                                                        IEEE 802.3 - 10   Mbps\n802.3 CSMA/CD Working Group\n                                                        IEEE 802.3u - 100 Mbps\n802.4 Token Bus\n802.5 Token Ring                                        IEEE 802.3z - 1000 Mbps\n\n802.6 Metropolitan Area Network (MAN)                   IEEE 802.3ab - 1000 Mbps\n802.7 BroadBand Technical Adv. Group (BBTAG)\n802.8 Fiber Optics Technical Adv. Group (FOTAG)\n802.9 Integrated Services LAN (ISLAN)\n802.10 Standard for Interoperable LAN Security (SILS)\n802.11 Wireless LAN (WLAN)                                     IEEE 802.11\n802.12 Demand Priority                                         IEEE 802.11a\n802.14 Cable-TV Based Broadband Communication                  IEEE 802.11b WiFi\nNetwork\n                                                               IEEE 802.11g\n802.15 Wireless Personal Area Network (WPAN)                   IEE 802.11 n\n802.16 Broadband Wireless Access (BBWA)\nRPRSG Resilient Packet Ring Study Group (RPRSG)", "topic": 10}, {"layer": 2, "page": 30, "text": "Wireless WAN Standards\n●\n    IEEE is the prime issuer of standards for wireless\n    networks.\n●\n    802.11 standard is Direct Sequence Spread Spectrum\n    (DSSS).\n     – DSSS applies to wireless devices operating within a 1\n       to 2 Mbps range.\n●\n    802.11b may also be called Wi-Fi™ or high-speed\n    wireless and refers to DSSS systems that operate at 1, 2,\n    5.5 and 11 Mbps.\n     – The majority of 802.11b devices still fail to match the\n       11 Mbps throughput and generally function in the 2 to\n       4 Mbps range.\n●\n    802.11a covers WLAN devices operating in the 5 GHZ\n    transmission band. throughput 54 Mbit/s\n●\n    802.11g provides the same throughout as 802.11a but\n    with backwards compatibility for 802.11b devices.\n●\n    802.11 n provides throughout as 300 Mbps", "topic": 10}, {"layer": 2, "page": 31, "text": "Wireless devices", "topic": 10}, {"layer": 2, "page": 32, "text": "How wireless LANs\n                   communicate\n●\n    Dado que la frecuencia de radio (RF) es\n    un medio compartido, pueden producirse\n    colisiones tal como lo hacen en\n    cableados medio compartido.\n●\n    La principal diferencia es que no hay un\n    método por el cual el nodo de origen es\n    capaz de detectar que se ha producido\n    una colisión.\n●\n    For that reason WLANs use Carrier\n    Sense       Multiple      Access/Collision\n    Avoidance (CSMA/CA).\n●\n    This    is    somewhat     like  Ethernet\n    CSMA/CD.", "topic": 10}, {"layer": 2, "page": 33, "text": "Práctica:\n●\n    Utilizar el software Packet Tracer 5.0 o mas\n    para simulación de una red de campus con\n    diferentes tipos de medios de comunicación\n    con WLAN con APs y laptops.", "topic": 10}, {"layer": 2, "page": 34, "text": "LAN: Ethernet", "topic": 11}, {"layer": 2, "page": 35, "text": "Tipos de Ethernet", "topic": 11}, {"layer": 2, "page": 36, "text": "Tipos de Ethernet", "topic": 11}, {"layer": 2, "page": 37, "text": "Frames Ethernet", "topic": 11}, {"layer": 2, "page": 38, "text": "100-Mbps Ethernet\n●\n    100-Mbps Ethernet is also known as Fast Ethernet\n    • 100BASE-TX is copper UTP\n    • 100BASE-FX is multimode optical fiber\n●\n    Frame format\n    • 100-Mbps frame format is the same as the 10-Mbps frame\n●\n    Parts of the transmission process\n    • Two separate encoding steps are used\n       • The first part of the encoding uses a technique called\n         4B/5B\n       • The second part of the encoding is the actual line\n         encoding specific to copper or fiber", "topic": 11}, {"layer": 2, "page": 39, "text": "●\n    4B/5B\n    – Cada 4 bits de datos se codifica en\n      códigos de 5-bit (Símbolos o señales)\n    – La palabra de código de 5 bit son\n      transmitidas usando NRZI\n    – Se logra 80% de eficiencia", "topic": 11}, {"layer": 2, "page": 40, "text": "", "topic": 11}, {"layer": 2, "page": 41, "text": "", "topic": 11}, {"layer": 2, "page": 42, "text": "1000-Mbps Ethernet\n●\n    1000-Mbps Ethernet or Gigabit Ethernet\n    Transmission\n    • Fiber and copper\n●\n    The 1000BASE-X IEEE 802.3z\n    • Specifies 1 Gbps full duplex over optical fiber\n●\n    1000BASE-TX, 1000BASE-SX, and 1000BASE-LX\n\n    • Frame Format\n       • Same format used for 10 and 100-Mbps Ethernet", "topic": 11}, {"layer": 2, "page": 43, "text": "1000-Mbps Ethernet\n●\n    1000BASE-T (IEEE 802.3ab) was developed to\n    provide additional bandwidth for:\n    • Intra-building backbones\n    • Inter-switch links\n    • Server farms\n    • Connections for high-end workstations\n    • Supports both half-duplex and full-duplex\n\n●\n    Fiber-based Gigabit Ethernet (1000BASE-X)\n    • Uses 8B/10B encoding (similar to 4B/5B)\n    • Uses encoding ZRZI Non Return to Zero Invertive", "topic": 11}, {"layer": 2, "page": 44, "text": "", "topic": 11}, {"layer": 2, "page": 45, "text": "1000Base-LX/SX\n●\n    NRZ signals are pulsed into the fiber\n    • Short-wavelength (1000BASE-SX )\n    • Long-wavelength (1000BASE-LX)\n\n●\n    Separate fibers\n    • Transmitting (Tx)\n    • Receiving (Rx)\n    • Inherently full duplex\n\n●\n    Gigabit Ethernet is the dominant technology for:\n    • Backbone installations\n    • General infrastructure", "topic": 11}, {"layer": 2, "page": 46, "text": "NRZ", "topic": 11}, {"layer": 2, "page": 47, "text": "NRZ Y NRZI", "topic": 11}, {"layer": 2, "page": 48, "text": "10 Gigabit Ethernet\n●\n    10GBASE-SR –\n    • Short distances, supports a range between 26 m to   82 m\n●\n    10GBASE-LX4 –\n    • Uses wide wavelength division multiplexing (WWDM)\n    • 240 to a 300 m over multimode fiber\n    • 10 km over single-mode fiber\n●\n    10GBASE-LR and 10GBASE-ER –\n    • Support 10 km and 40 km over single-mode fiber\n●\n    10GBASE-SW, 10GBASE-LW, and 10GBASE-EW –\n    • Known collectively as 10GBASE-W", "topic": 11}, {"layer": 2, "page": 49, "text": "Future of Ethernet\n●\n    The future of networking media is three-fold:\n    1.Copper (up to 10-1000 Mbps, perhaps\n      more)\n    2.Wireless (approaching 1000 Mbps, perhaps\n      more)\n    3.Optical fiber (currently at 50,000 Mbps and\n      soon to be more)\n\n●\n    Copper and wireless media have certain\n    physical and practical limitations", "topic": 11}, {"layer": 2, "page": 50, "text": "Ejercicios Extra-clase de análisis de tráfico\nutilizando la herramienta Wireshark\n\n\n TELNET, PING, IP, ETHERNET, UDP, TCP,\n        ARP, http, https, SMTP", "topic": 11}, {"layer": 2, "page": 51, "text": "Dispositivos de Capa 2", "topic": 12}, {"layer": 2, "page": 52, "text": "NICs\n●\n    Provée el puerto para la conexión de\n    red", "topic": 12}, {"layer": 2, "page": 53, "text": "Factores de Selección de la\n               NIC\n●\n    Al elegir la NIC se debe tener en\n    cuenta:\n    • tipo de red\n        • Ethernet (10/100/1000 Mbps)\n    • tipo de medios\n        • UTP, F.O., Wireless\n    • tipo de bus del sistema\n        • PCI, PCMCIA, USB", "topic": 12}, {"layer": 2, "page": 54, "text": "PUENTES (BRIDGE)\n●\n    Dispositivo de capa 2 conecta\n    dos segmentos de LAN\n●\n    Trabajan a nivel de software\n    generando latencia\n●\n    Filtrar el tráfico de una LAN\n●\n    Verifica la dirección de cada\n    dispositivo de la LAN\n●\n    Crea una lista de MAC para\n    toma de decisiones\n●\n    Cada NIC tiene una dirección\n    MAC exclusiva\n●\n    El puente conecta solamente\n    dos segmentos a la vez\n●\n    Los routers y los switches han\n    desplazado al puente", "topic": 12}, {"layer": 2, "page": 55, "text": "SWITCH\n●\n    Dispositivo de la capa 2\n●\n    Puente multipuerto\n\n●\n    Toman decisiones basados\n    en las direcciones MAC\n\n●\n    LANs mucho más eficiente", "topic": 12}, {"layer": 2, "page": 56, "text": "SWITCH\n\n\n●\n    Segmenta una red en dominios de colisión tantos como\n    puertos activos posea\n●\n    “Conmutan\" datos sólo desde el puerto de origen al de\n    destino\n●\n    Suministra a cada puerto el ancho de banda total", "topic": 12}, {"layer": 2, "page": 57, "text": "", "topic": 12}, {"layer": 2, "page": 58, "text": "●   Trabaja conmutando tramas de datos\n●   Aprende direcciones, reenviar, filtrar paquetes y\n    evitar bucles\n●   Controlar el tráficos de múltiples segmentos", "topic": 12}, {"layer": 2, "page": 59, "text": "Ventajas de los Switches\n●\n    Mucho más rápidos que los puentes\n    – Basados en Hardware, no en Software\n●\n    Soporta nuevos usos\n    – EJ. LANs virtuales (VLANs)\n●\n  Reduce los dominios de colisión\n●\n  Costo efectivo\n    – Pueden reemplazar de manera muy\n      simple un hub con el mismo cableado\n      ●\n          Interrupción mínima", "topic": 12}, {"layer": 2, "page": 60, "text": "Layer 2 and layer 3 switching\n\n\n\n\n●\n    A layer 3 switch is typically a layer 2 switch that includes a\n    routing process\n●\n    Layer 3 switching has many meanings and in many cases is\n    just a marketing term.\n●\n    Layer 3 switching is a function of the network layer.\n●\n    The Layer 3 header information is examined and the packet is\n    forwarded based on the IP address.", "topic": 12}, {"layer": 2, "page": 61, "text": "Symmetric and asymmetric\n      switching", "topic": 12}, {"layer": 2, "page": 62, "text": "Tres métodos de conmutación\n\n\n●\n    Store-and-forward – The entire frame is received\n    before any forwarding takes place.\n     – The destination and source addresses are read and\n       filters are applied before the frame is forwarded.\n     – CRC (count of redundancy cyclical)| Check done is\n       forwarded\n●\n    Cut-through – The frame is forwarded through the\n    switch before the entire frame is received.\n     – This mode decreases the latency of the\n       transmission, but also reduces error detection.", "topic": 13}, {"layer": 2, "page": 63, "text": "●   Free of fragment –este es una modificacion de metodo de corte, el\n    switch lee los primeros 64 bytes antes de transmitir la trama.", "topic": 13}, {"layer": 2, "page": 64, "text": "Dominios de Broadcast\n●\n  Todos los hosts conectados al mismo\n  switch permanecen en el mismo\n  dominio de broadcast\n●\n  Un broadcast desde un nodo será visto\n  por todos los otros nodos conectados\n  en el mismo switch", "topic": 13}, {"layer": 2, "page": 65, "text": "APRENDIZAJE DE DIRECCIONES\n\n●\n  Un switch crea circuitos Virtuales entre\n  segmentos identificando las\n  direcciones MAC de destino asociada\n  a un puerto\n●\n  Cuando un switch se inicia no posee\n  datos MAC por lo que inunda todos los\n  puertos para obtener la MAC", "topic": 13}, {"layer": 2, "page": 66, "text": "BUCLES EN LA CAPA 2\n●\n  Bucles y tramas duplicadas son resueltas por\n  el protocolo STP(Protocolo de Arbol de\n  Extensión, Spanning Tree estándar IEEE\n  802.1)\n●\n  Este protocolo explora constantemente la red\n  y bloquea puertos redundantes, y reconfigura\n  puertos del switch o bridge cuando se\n  produce un fallo.\n●\n  Cuando hay alguna anormalidad cambian el\n  estado de un puerto STP, sin que se pierda la\n  conectividad de la red, Usan Paquetes BPDU", "topic": 14}, {"layer": 2, "page": 67, "text": "PROCESO STP\n1.Elección del Switch Raíz.- En un dominio de\n  difusión solo puede existir un switch de\n  difusión, se lo elige seleccionando el que\n  posea menor prioridad. (se suma la prioridad\n  por defecto 1 al 65536 y el ID del switch\n  MAC) por defecto la prioridad es de\n  32768(215). Los otros switch son Switch no\n  raiz.\n2.Puerto Raíz.-Es la ruta de menor coste\n  desde el Switch no raíz hasta el switch raíz.\n  (su estado es enviando o transmitiendo)", "topic": 14}, {"layer": 2, "page": 68, "text": "PROCESO STP\n\n3.Puertos designados.- conectan los\n  segmentos al switch raiz, y solo debe de\n  haber un puerto designado por segmento.\n  (se encuentran en estado de Transmisión)\n  Los puertos no designados, normalmente se\n  encuentran en estado de retransmisión, y los\n  puertos no designados su estado es\n  bloqueado.", "topic": 14}, {"layer": 2, "page": 69, "text": "PROCESO STP\nESTADOS DE LOS PUERTOS DE STP\n\nBLOQUEADO, Escuchando, Aprendiendo,\nEnviando", "topic": 14}, {"layer": 2, "page": 70, "text": "PROCESO STP", "topic": 14}, {"layer": 2, "page": 71, "text": "Segmentación con Routers", "topic": 14}, {"layer": 2, "page": 72, "text": "Tarea Extra-Clase:\n•Realizar un cuadro comparativo de\ncaracterísticas técnicas & estándares de 3\nswitches de diferentes fabricantes (Cisco,\nEnterasys, HP, D-link, TPLINK,\nTRENDNET, ETC...).", "topic": 14}]};
